using Microsoft.EntityFrameworkCore;
using Microsoft.Data.Sqlite;
using var connection = new SqliteConnection("Data Source=:memory:");
connection.Open();
var options = new DbContextOptionsBuilder<School>().UseSqlite(connection).Options;
using var db = new School(options);
db.Database.EnsureCreated();
db.Departments.Add(new Department { Name = "CNTT", Students = new List<Student> {
    new() { Name = "An", Score = 8 }, new() { Name = "Chi", Score = 5 }
}});
db.SaveChanges();
db.ChangeTracker.Clear();
var students = db.Students.Include(s => s.Department).Where(s => s.Score >= 8).OrderBy(s => s.Id).ToList();
Console.WriteLine(string.Join(", ", students.Select(s => s.Name + ":" + s.Department.Name)));
class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public ICollection<Student> Students { get; set; } = new List<Student>();
}
class Student
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public int Score { get; set; }
    public int DepartmentId { get; set; }
    public Department Department { get; set; } = null!;
}
class School(DbContextOptions<School> options) : DbContext(options)
{
    public DbSet<Student> Students => Set<Student>();
    public DbSet<Department> Departments => Set<Department>();
}

